-- منهج اللغة العربية للصف الخامس ف١: «لغتي الجميلة» (مهاراتي في القراءة + مهاراتي في الكتابة).
-- الوحدات هي محاور الكتاب الثلاثة، وفي كلٍّ منها دروس القراءة (استماع، تحدّث، درسان، نصّ شعري، قراءة حرّة)
-- ثم دروس الكتابة الثلاثة مقسّمةً إلى أجزائها (نحو، إملاء، خطّ النسخ، تعبير). الصفحات بأرقام الكتاب المطبوعة؛
-- صفحة PDF = المطبوعة + ١ ← الإزاحة ٢. ودليل المعلم: صفحة PDF = المطبوعة ← الإزاحة ١. متعادلة.
delete from public.curriculum where semester='الفصل الأول' and grade=5 and subject='اللغة العربية';
update public.book_sources set offset_pages=2, updated_at=now() where semester='الفصل الأول' and grade='5' and subject='اللغة العربية';
update public.teacher_guides tg set offset_pages=1, status='indexed', indexed_at=now(), toc=(
  select jsonb_agg(jsonb_build_object('guide_unit',c.unit,'guide_lesson',c.lesson,'guide_page',v.p,'matched_curriculum_id',c.id,'confidence','high') order by c.sort)
  from public.curriculum c join (values (1,35),(2,38),(3,41),(4,45),(5,50),(6,54),(7,129),(8,132),(9,139),(10,141),(11,143),(12,145),(13,149),(14,150),(15,153),(16,156),(17,159),(18,63),(19,69),(20,72),(21,76),(22,81),(23,86),(24,165),(25,169),(26,173),(27,175),(28,178),(29,182),(30,185),(31,186),(32,187),(33,192),(34,193),(35,95),(36,101),(37,104),(38,111),(39,116),(40,122),(41,199),(42,202),(43,205),(44,208),(45,210),(46,214),(47,218),(48,219),(49,222),(50,225),(51,226)) v(s,p) on v.s=c.sort
  where c.semester='الفصل الأول' and c.grade=5 and c.subject='اللغة العربية')
where tg.semester='الفصل الأول' and tg.grade=5 and tg.subject='اللغة العربية';
